```yaml
name: Weekly Repo Status

on:
  schedule:
    # Runs every Monday at 00:00 UTC (covers the previous week)
    - cron: '0 0 * * 1'
  workflow_dispatch:

permissions:
  contents: read
  issues: write

jobs:
  report:
    runs-on: ubuntu-latest
    steps:
      - name: Generate and post weekly status
        uses: actions/github-script@v6
        with:
          script: |
            // Helper to format dates as "Feb 20–27, 2026"
            const formatDateRange = (start, end) => {
              const options = { month: 'short', day: 'numeric', year: 'numeric' };
              return `${start.toLocaleDateString('en-US', options)}–${end.toLocaleDateString('en-US', options)}`;
            };

            // Determine the previous week (Monday–Sunday)
            const now = new Date();
            const utcNow = new Date(now.toUTCString());
            const day = utcNow.getUTCDay(); // 0=Sun, 1=Mon, ...
            const sunday = new Date(utcNow);
            sunday.setUTCDate(utcNow.getUTCDate() - day); // last Sunday
            const monday = new Date(sunday);
            monday.setUTCDate(sunday.getUTCDate() - 6); // previous Monday

            const startISO = monday.toISOString();
            const endISO = sunday.toISOString();
            const title = `Weekly Repo Status — ${formatDateRange(monday, sunday)}`;

            // Fetch merged PRs in the date range
            const mergedPRs = await github.paginate('GET /search/issues', {
              q: `repo:${context.repo.owner}/${context.repo.repo} is:pr is:merged merged:${startISO}..${endISO}`,
              per_page: 100
            });
            const mergedCount = mergedPRs.length;

            // Fetch closed issues in the date range
            const closedIssues = await github.paginate('GET /search/issues', {
              q: `repo:${context.repo.owner}/${context.repo.repo} is:issue is:closed closed:${startISO}..${endISO}`,
              per_page: 100
            });
            const closedCount = closedIssues.length;

            // Fetch opened issues in the date range
            const openedIssues = await github.paginate('GET /search/issues', {
              q: `repo:${context.repo.owner}/${context.repo.repo} is:issue is:open created:${startISO}..${endISO}`,
              per_page: 100
            });

            // Group issues by label
            const groupByLabel = (items) => {
              const groups = {};
              items.forEach(item => {
                const labels = item.labels.map(l => l.name);
                if (labels.length === 0) {
                  groups['no-label'] = groups['no-label'] || [];
                  groups['no-label'].push(item);
                } else {
                  labels.forEach(l => {
                    groups[l] = groups[l] || [];
                    groups[l].push(item);
                  });
                }
              });
              return groups;
            };

            const mergedGroups = groupByLabel(mergedPRs);
            const closedGroups = groupByLabel(closedIssues);
            const openedGroups = groupByLabel(openedIssues);

            // Build markdown body
            let body = `## 🌟 Weekly Repo Status — ${formatDateRange(monday, sunday)}\n\n`;
            body += `What an outstanding week! The team shipped **${mergedCount} merged PRs**, tackled **${closedCount} closed issues**, and delivered a brand‑new skill alongside major infrastructure upgrades. Here's the full picture. 🚀\n\n`;
            body += `## 📊 Issues This Week\n\n`;
            body += `### Issues Opened: ${openedIssues.length}\n\n`;
            body += `| Skill | Count | Issues |\n|-------|-------|--------|\n`;
            for (const [label, items] of Object.entries(openedGroups)) {
              const links = items.map(i => `[#${i.number}](${i.html_url})`).join(' ');
              body += `| ${label} | ${items.length} | ${links} |\n`;
            }
            body += `\n### Issues Closed: ${closedCount}\n\n`;
            body += `| Skill | Issues |\n|-------|--------|\n`;
            for (const [label, items] of Object.entries(closedGroups)) {
              const links = items.map(i => `[#${i.number}](${i.html_url})`).join(' ');
              body += `| ${label} | ${links} |\n`;
            }

            // Create a new issue with the report
            await github.issues.create({
              owner: context.repo.owner,
              repo: context.repo.repo,
              title: title,
              body: body
            });
```

